// Convierte el mensaje de Telegram al payload que espera NestJS.
// Si hay archivo adjunto (document/photo), lo descarga y codifica en base64.
const msg = items[0].json.message;
const chatId = String(msg.chat.id);
const text = msg.text || msg.caption || '';

let archivoBase64 = null;
let filename = null;
let contentType = null;

// El nodo Telegram puede entregar el archivo via $binary; aquí dejamos el hueco listo.
if ($binary && $binary.data) {
  archivoBase64 = $binary.data.data;
  filename = $binary.data.fileName || 'adjunto';
  contentType = $binary.data.mimeType || 'application/octet-stream';
}

return [{
  json: {
    tipoCanal: 'TELEGRAM',
    identificadorCanal: chatId,
    mensaje: text,
    archivoBase64,
    filename,
    contentType
  }
}];
